#!/usr/bin/env python3
"""Grade the check-gate `calc` task: run the pristine visible tests plus
hidden tests derived from the task's specification against a copy of the
workspace whose own tests/ directory is replaced. Editing the workspace's tests
changes nothing here. The last output line is `<failed> failed, <passed> passed`."""
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

TEST_FILES = {'tests/__init__.py': '# Unit tests.\n', 'tests/run.py': '"""Run the unit tests under tests/ and report them like pytest\'s summary:\nthe failure details first, then one `FAILED <test> - <reason>` line per\nfailing test and a count line. Exit status 1 when anything failed."""\nimport os\nimport sys\nimport unittest\n\n\ndef main():\n    here = os.path.dirname(os.path.abspath(__file__))\n    root = os.path.dirname(here)\n    sys.path.insert(0, root)\n    suite = unittest.defaultTestLoader.discover(here, pattern="test_*.py", top_level_dir=root)\n    result = unittest.TestResult()\n    suite.run(result)\n    failed = result.failures + result.errors\n    for test, trace in failed:\n        print("_" * 12 + " " + test.id() + " " + "_" * 12)\n        print(trace.rstrip())\n        print()\n    failing_methods = set()\n    for test, trace in failed:\n        case = getattr(test, "test_case", test)\n        failing_methods.add(case.id())\n        parts = case.id().rsplit(".", 2)\n        if len(parts) == 3:\n            module, cls, method = parts\n            name = "%s.py::%s::%s" % (module.replace(".", "/"), cls, method)\n        else:\n            name = case.id()\n        if case is not test:\n            name += " " + test._subDescription()\n        lines = trace.strip().splitlines()\n        reason = lines[-1] if lines else ""\n        print("FAILED %s - %s" % (name, reason))\n    print("%d failed, %d passed" % (len(failing_methods), result.testsRun - len(failing_methods)))\n    return 1 if failed else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'tests/test_arithmetic.py': 'import unittest\n\nfrom calc import CalcError, run\n\nclass CalcArithmeticTest(unittest.TestCase):\n    def test_print_sum(self):\n        self.assertEqual(run(\'print 1 + 2\'), [\'3\'])\n\n    def test_precedence(self):\n        self.assertEqual(run(\'print 2 + 3 * 4\'), [\'14\'])\n\n    def test_parentheses(self):\n        self.assertEqual(run(\'print (2 + 3) * 4\'), [\'20\'])\n\n    def test_true_division(self):\n        self.assertEqual(run(\'print 7 / 2\'), [\'3.5\'])\n\n    def test_true_division_whole(self):\n        self.assertEqual(run(\'print 6 / 2\'), [\'3.0\'])\n\n    def test_floor_division_and_modulo(self):\n        self.assertEqual(run(\'print 7 // 2; print -7 // 2; print 7 % 3; print -7 % 3\'), [\'3\', \'-4\', \'1\', \'2\'])\n\n    def test_power_right_associative(self):\n        self.assertEqual(run(\'print 2 ^ 3 ^ 2\'), [\'512\'])\n\n    def test_unary_minus_and_power(self):\n        self.assertEqual(run(\'print -2 ^ 2\'), [\'-4\'])\n\n    def test_negative_exponent(self):\n        self.assertEqual(run(\'print 2 ^ -1\'), [\'0.5\'])\n\n    def test_float_repr(self):\n        self.assertEqual(run(\'print 0.1 + 0.2\'), [\'0.30000000000000004\'])\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_statements.py': 'import unittest\n\nfrom calc import CalcError, run\n\nclass CalcStatementsTest(unittest.TestCase):\n    def test_variables(self):\n        self.assertEqual(run(\'let x = 4; let y = x * 2; print y\'), [\'8\'])\n\n    def test_reassignment(self):\n        self.assertEqual(run(\'let x = 1; let x = x + 1; print x\'), [\'2\'])\n\n    def test_comments_and_newlines(self):\n        self.assertEqual(run(\'let a = 1; # one\\nprint a + 1\'), [\'2\'])\n\n    def test_empty_statements(self):\n        self.assertEqual(run(\'print 1;; print 2;\'), [\'1\', \'2\'])\n\n    def test_expression_statement(self):\n        self.assertEqual(run(\'1 + 1; print 3\'), [\'3\'])\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_functions.py': 'import unittest\n\nfrom calc import CalcError, run\n\nclass CalcFunctionsTest(unittest.TestCase):\n    def test_abs(self):\n        self.assertEqual(run(\'print abs(-3); print abs(-2.5)\'), [\'3\', \'2.5\'])\n\n    def test_min_max(self):\n        self.assertEqual(run(\'print min(3, 1, 2); print max(3, 1, 2)\'), [\'1\', \'3\'])\n\n    def test_sqrt(self):\n        self.assertEqual(run(\'print sqrt(16)\'), [\'4.0\'])\n\n    def test_round_half_away_from_zero(self):\n        self.assertEqual(run(\'print round(2.5); print round(-2.5)\'), [\'3\', \'-3\'])\n\n    def test_round_digits(self):\n        self.assertEqual(run(\'print round(1.005, 2)\'), [\'1.01\'])\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_errors.py': 'import unittest\n\nfrom calc import CalcError, run\n\nclass CalcErrorsTest(unittest.TestCase):\n    def test_calc_error_is_an_exception(self):\n        self.assertTrue(issubclass(CalcError, Exception))\n\n    def test_unexpected_character(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'print 1 $ 2\')\n        self.assertEqual(str(caught.exception), "1:9: unexpected character \'$\'")\n\n    def test_unexpected_token(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'print )\')\n        self.assertEqual(str(caught.exception), "1:7: unexpected token \')\'")\n\n    def test_unexpected_end(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'print 1 +\')\n        self.assertEqual(str(caught.exception), \'1:10: unexpected end of input\')\n\n    def test_undefined_variable(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'print x\')\n        self.assertEqual(str(caught.exception), "1:7: undefined variable \'x\'")\n\n    def test_unknown_function(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'print foo(1)\')\n        self.assertEqual(str(caught.exception), "1:7: unknown function \'foo\'")\n\n    def test_arity(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'print sqrt(1, 2)\')\n        self.assertEqual(str(caught.exception), "1:7: function \'sqrt\' expects 1 argument")\n\n    def test_division_by_zero(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'print 1 / 0\')\n        self.assertEqual(str(caught.exception), \'1:9: division by zero\')\n\n    def test_sqrt_of_negative(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'print sqrt(-1)\')\n        self.assertEqual(str(caught.exception), \'1:7: math domain error\')\n\n    def test_position_on_second_line(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'let a = 1;\\nprint b\')\n        self.assertEqual(str(caught.exception), "2:7: undefined variable \'b\'")\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_hidden_calc.py': 'import unittest\n\nfrom calc import CalcError, run\n\nclass CalcHiddenTest(unittest.TestCase):\n    def test_whole_program_parses_before_running(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'print 1 / 0; print )\')\n        self.assertEqual(str(caught.exception), "1:20: unexpected token \')\'")\n\n    def test_keyword_as_name(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'let print = 1\')\n        self.assertEqual(str(caught.exception), "1:5: unexpected token \'print\'")\n\n    def test_floor_division_by_zero(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'print 5 // 0\')\n        self.assertEqual(str(caught.exception), \'1:9: division by zero\')\n\n    def test_modulo_by_zero(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'let z = 0;\\n  print 5 % z\')\n        self.assertEqual(str(caught.exception), \'2:11: division by zero\')\n\n    def test_float_floor_division(self):\n        self.assertEqual(run(\'print 7.5 // 2\'), [\'3.0\'])\n\n    def test_big_int_power(self):\n        self.assertEqual(run(\'print 2 ^ 64\'), [\'18446744073709551616\'])\n\n    def test_round_decimal_text(self):\n        self.assertEqual(run(\'print round(2.675, 2)\'), [\'2.68\'])\n\n    def test_round_int_with_digits(self):\n        self.assertEqual(run(\'print round(3, 1)\'), [\'3.0\'])\n\n    def test_min_mixed(self):\n        self.assertEqual(run(\'print min(3, 1.5, 2)\'), [\'1.5\'])\n\n    def test_round_arity(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'print round(1, 2, 3)\')\n        self.assertEqual(str(caught.exception), "1:7: function \'round\' expects 1 or 2 arguments")\n\n    def test_min_arity(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'print min()\')\n        self.assertEqual(str(caught.exception), "1:7: function \'min\' expects at least 1 argument")\n\n    def test_abs_arity(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'print abs(1, 2)\')\n        self.assertEqual(str(caught.exception), "1:7: function \'abs\' expects 1 argument")\n\n    def test_function_name_as_variable(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'print abs\')\n        self.assertEqual(str(caught.exception), "1:7: undefined variable \'abs\'")\n\n    def test_no_real_power(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'print (-8) ^ 0.5\')\n        self.assertEqual(str(caught.exception), \'1:12: math domain error\')\n\n    def test_trailing_comment_and_tabs(self):\n        self.assertEqual(run(\'print\\t1 # done\'), [\'1\'])\n\n    def test_number_with_trailing_dot(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'print 1.\')\n        self.assertEqual(str(caught.exception), "1:8: unexpected character \'.\'")\n\n    def test_nested_calls(self):\n        self.assertEqual(run(\'print max(abs(-3), sqrt(4))\'), [\'3\'])\n\n    def test_stacked_unary(self):\n        self.assertEqual(run(\'print +-+2\'), [\'-2\'])\n\n    def test_end_of_input_after_newline(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'print (1 + 2\\n\')\n        self.assertEqual(str(caught.exception), \'2:1: unexpected end of input\')\n\n    def test_missing_semicolon(self):\n        with self.assertRaises(CalcError) as caught:\n            run(\'print 1 print 2\')\n        self.assertEqual(str(caught.exception), "1:9: unexpected token \'print\'")\n\n    def test_power_of_float_whole(self):\n        self.assertEqual(run(\'print 2.0 ^ 2\'), [\'4.0\'])\n\n\nif __name__ == "__main__":\n    unittest.main()\n'}

SKIP = {"tests", ".git", ".home", "__pycache__", "events.jsonl"}


def main():
    workspace = Path(sys.argv[1]) if len(sys.argv) > 1 else Path.cwd()
    with tempfile.TemporaryDirectory() as tmp:
        root = Path(tmp) / "workspace"
        root.mkdir()
        for entry in workspace.iterdir():
            if entry.name in SKIP or entry.name.startswith(".") or entry.is_symlink():
                continue
            if entry.is_dir():
                shutil.copytree(entry, root / entry.name, symlinks=False,
                                ignore=shutil.ignore_patterns("__pycache__"))
            elif entry.is_file():
                shutil.copy2(entry, root / entry.name)
        for rel, text in TEST_FILES.items():
            target = root / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(text, encoding="utf-8")
        try:
            result = subprocess.run([sys.executable, "tests/run.py"], cwd=root, capture_output=True,
                                    text=True, timeout=90)
        except subprocess.TimeoutExpired:
            print("tests timed out")
            return 1
        output = result.stdout + result.stderr
        print(output[-4000:])
        return 0 if result.returncode == 0 else 1


if __name__ == "__main__":
    sys.exit(main())
